/**
 * Normalizes a value to an array:
 * - `undefined` becomes `[]`
 * - a non-array value is wrapped in a single-element array
 * - an array is returned unchanged
 */
export function toArray<T>(value: T | T[] | undefined): T[] {
  if (value === undefined) {
    return [];
  }
  return Array.isArray(value) ? value : [value];
}

export type ValidationResult = { isValid: true } | { isValid: false; error: string };

// Top-level keys we are willing to accept in a user supplied ruleset. Anything
// outside of this set (notably `functions`, which allows arbitrary code) is
// rejected.
const ALLOWED_TOP_LEVEL_KEYS = new Set([
  'extends',
  'rules',
  'documentationUrl',
  'aliases',
  'overrides',
  'formats',
  'parserOptions',
]);

// Spectral's built-in core functions. Custom (`functions`) are intentionally
// unsupported, so `then.function` must reference one of these.
const BUILTIN_FUNCTIONS = new Set([
  'alphabetical',
  'casing',
  'defined',
  'enumeration',
  'falsy',
  'length',
  'pattern',
  'schema',
  'truthy',
  'typedEnum',
  'undefined',
  'unreferencedReusableObject',
  'or',
  'xor',
]);

// Valid Spectral severity strings usable as a rule shorthand.
const SEVERITY_STRINGS = new Set(['error', 'warn', 'info', 'hint', 'off']);

// Keys that could be used to pollute the prototype chain.
const PROTO_POLLUTING_TOKENS = ['__proto__', 'prototype', 'constructor'];

const isPlainObject = (value: unknown): value is Record<string, unknown> =>
  value !== null && typeof value === 'object' && !Array.isArray(value);

/**
 * Validates the raw content of a Spectral ruleset file (YAML or JSON).
 *
 * Returns `{ isValid: true }` when the content is a safe, well-formed ruleset,
 * otherwise `{ isValid: false, error }` with a human readable explanation.
 */
export function validateSpectralRuleset(content: string): ValidationResult {
  if (!content || !content.trim()) {
    return { isValid: false, error: 'Ruleset is empty.' };
  }

  let parsed: unknown;
  try {
    parsed = parse(content);
  } catch (err) {
    return {
      isValid: false,
      error: `Ruleset could not be parsed as YAML or JSON: ${(err as Error).message}`,
    };
  }

  if (!isPlainObject(parsed)) {
    return { isValid: false, error: 'Ruleset must be an object at the top level.' };
  }

  const keys = Object.keys(parsed);
  if (keys.length === 0) {
    return { isValid: false, error: 'Ruleset must declare at least one of "extends" or "rules".' };
  }

  for (const key of keys) {
    if (!ALLOWED_TOP_LEVEL_KEYS.has(key)) {
      return { isValid: false, error: `Unsupported top-level key "${key}".` };
    }
  }

  if ('extends' in parsed) {
    const extendsError = validateExtends(parsed.extends);
    if (extendsError) {
      return { isValid: false, error: extendsError };
    }
  }

  if ('documentationUrl' in parsed) {
    const urlError = validateDocumentationUrl(parsed.documentationUrl);
    if (urlError) {
      return { isValid: false, error: urlError };
    }
  }

  if ('rules' in parsed) {
    const rulesError = validateRules(parsed.rules);
    if (rulesError) {
      return { isValid: false, error: rulesError };
    }
  }

  return { isValid: true };
}

function validateExtends(value: unknown): string | null {
  for (const entry of toArray(value)) {
    if (typeof entry !== 'string') {
      return '"extends" entries must be strings.';
    }
  }
  return null;
}

function validateRules(rules: unknown): string | null {
  if (!isPlainObject(rules)) {
    return '"rules" must be an object.';
  }

  for (const ruleName of Object.keys(rules)) {
    const body = rules[ruleName];

    // Shorthand: a boolean toggles a rule on/off.
    if (typeof body === 'boolean') {
      continue;
    }

    // Shorthand: a severity string overrides an inherited rule's severity.
    if (typeof body === 'string') {
      if (SEVERITY_STRINGS.has(body)) {
        continue;
      }
      return `Rule "${ruleName}" must be an object, boolean, or severity string.`;
    }

    if (!isPlainObject(body)) {
      return `Rule "${ruleName}" must be an object, boolean, or severity string.`;
    }

    // Full rule definition (object body).
    if (PROTO_POLLUTING_TOKENS.includes(ruleName)) {
      return `Rule name "${ruleName}" is not allowed.`;
    }

    const bodyError = validateRuleBody(body);
    if (bodyError) {
      return bodyError;
    }
  }

  return null;
}

function validateRuleBody(body: Record<string, unknown>): string | null {
  if ('documentationUrl' in body) {
    const urlError = validateDocumentationUrl(body.documentationUrl);
    if (urlError) {
      return urlError;
    }
  }

  if ('given' in body) {
    const givenError = validateGiven(body.given);
    if (givenError) {
      return givenError;
    }
  }

  if ('then' in body) {
    const thenError = validateThen(body.then);
    if (thenError) {
      return thenError;
    }
  }

  return null;
}

function validateGiven(given: unknown): string | null {
  const expressions = Array.isArray(given) ? given : [given];
  for (const expression of expressions) {
    // Non-string given values (e.g. objects) are not JSONPath expressions and
    // are skipped.
    if (typeof expression !== 'string') {
      continue;
    }
    for (const token of PROTO_POLLUTING_TOKENS) {
      if (expression.includes(token)) {
        return `Rule "given" expression contains a disallowed token "${token}".`;
      }
    }
  }
  return null;
}

function validateThen(then: unknown): string | null {
  const entries = Array.isArray(then) ? then : [then];
  for (const entry of entries) {
    // When `then` is an array, non-object entries are skipped.
    if (!isPlainObject(entry)) {
      continue;
    }

    if ('field' in entry) {
      const fieldError = validateThenField(entry.field);
      if (fieldError) {
        return fieldError;
      }
    }

    if ('function' in entry) {
      const fn = entry.function;
      if (typeof fn !== 'string' || !BUILTIN_FUNCTIONS.has(fn)) {
        return `"then.function" "${String(fn)}" is not an allowed function.`;
      }
    }
  }
  return null;
}

function validateThenField(field: unknown): string | null {
  if (typeof field !== 'string') {
    return null;
  }
  const disallowed = [...PROTO_POLLUTING_TOKENS, '.', '[', ']'];
  for (const token of disallowed) {
    if (field.includes(token)) {
      return `"then.field" "${field}" contains a disallowed value.`;
    }
  }
  return null;
}

function validateDocumentationUrl(value: unknown): string | null {
  // Non-string documentationUrl values are skipped.
  if (typeof value !== 'string') {
    return null;
  }
  try {
    const url = new URL(value);
    if (url.protocol !== 'https:') {
      return 'documentationUrl must use the https scheme.';
    }
  } catch {
    return 'documentationUrl must be a valid https URL.';
  }
  return null;
}
