import fs from 'node:fs';
import path from 'node:path';

import { parse, stringify } from 'yaml';

import { isPrivateOrLoopbackHost } from './private-host';
import { toArray, validateSpectralRuleset } from './spectral-ruleset-validator';

// Maximum depth of local `extends` nesting. The root document sits at depth 0,
// so a chain deeper than this many levels is rejected.
const MAX_EXTENDS_DEPTH = 5;

// Matches an absolute URL with a scheme and authority (e.g. `https://…`,
// `http://…`, `ftp://…`). Deliberately does NOT match `spectral:oas` (no `//`)
// or local file paths.
const URL_LIKE = /^[a-z][a-z0-9+.-]*:\/\//i;

const isPlainObject = (value: unknown): value is Record<string, unknown> =>
  value !== null && typeof value === 'object' && !Array.isArray(value);

const isBuiltinIdentifier = (entry: string): boolean => entry.startsWith('spectral:');

const isUrlLike = (entry: string): boolean => URL_LIKE.test(entry);

const isFilePath = (entry: string): boolean => {
  const lower = entry.toLowerCase();
  return (
    entry.startsWith('/') ||
    entry.startsWith('./') ||
    entry.startsWith('../') ||
    entry.includes('/') ||
    lower.endsWith('.yaml') ||
    lower.endsWith('.yml')
  );
};

const isYamlFile = (entry: string): boolean => {
  const lower = entry.toLowerCase();
  return lower.endsWith('.yaml') || lower.endsWith('.yml');
};

const isIpLiteral = (hostname: string): boolean =>
  /^\d{1,3}(\.\d{1,3}){3}$/.test(hostname) ||
  hostname.includes(':') ||
  (hostname.startsWith('[') && hostname.endsWith(']'));

/**
 * Reads a Spectral ruleset from `filePath` and returns a bundled YAML string.
 *
 * Local file `extends` references are recursively flattened: their rules are
 * merged into the parent's rules, with the parent's definitions winning on a
 * name collision, and the file paths are removed from the output. Built-in
 * spectral identifiers (`spectral:oas`, …) and validated remote HTTPS
 * references are preserved (de-duplicated) in the output `extends`; remote rule
 * content is never merged.
 */
export async function bundleSpectralRuleset(filePath: string): Promise<string> {
  const outExtends: string[] = [];
  const seenExtends = new Set<string>();

  const addExtends = (entry: string): void => {
    if (!seenExtends.has(entry)) {
      seenExtends.add(entry);
      outExtends.push(entry);
    }
  };

  const rules = await loadAndMerge(filePath, new Set<string>(), 0, addExtends);

  const output: { extends?: string[]; rules?: Record<string, unknown> } = {};
  if (outExtends.length > 0) {
    output.extends = outExtends;
  }
  if (Object.keys(rules).length > 0) {
    output.rules = rules;
  }

  return stringify(output);
}

/**
 * Loads a single local ruleset file, recursively flattening its local
 * `extends`, and returns the merged `rules` object for this subtree.
 */
async function loadAndMerge(
  filePath: string,
  ancestors: Set<string>,
  depth: number,
  addExtends: (entry: string) => void,
): Promise<Record<string, unknown>> {
  if (depth > MAX_EXTENDS_DEPTH) {
    throw new Error('"extends" nested too deeply.');
  }

  const resolvedPath = path.resolve(filePath);
  if (ancestors.has(resolvedPath)) {
    throw new Error(`"extends" cycle detected at "${resolvedPath}".`);
  }
  const nextAncestors = new Set(ancestors).add(resolvedPath);

  const content = await fs.promises.readFile(filePath, 'utf8');
  const parsed = parse(content);

  if (!isPlainObject(parsed)) {
    throw new Error(`Ruleset "${filePath}" must be an object at the top level.`);
  }
  if ('functions' in parsed) {
    throw new Error(`Invalid Spectral ruleset "${filePath}": custom "functions" are not supported.`);
  }

  // Rules contributed by children; parent rules are overlaid on top afterwards.
  const merged: Record<string, unknown> = {};

  for (const entry of toArray(parsed.extends)) {
    if (Array.isArray(entry)) {
      throw new Error('"extends" entry uses the unsupported tuple format.');
    }
    if (typeof entry !== 'string') {
      throw new Error(`"${String(entry)}" is not a valid spectral identifier, file path, or valid URL.`);
    }

    if (isBuiltinIdentifier(entry)) {
      addExtends(entry);
      continue;
    }

    if (isUrlLike(entry)) {
      await assertRemoteUrlAllowed(entry);
      await fetchAndValidateRemote(entry, depth + 1);
      addExtends(entry);
      continue;
    }

    if (isFilePath(entry)) {
      if (!isYamlFile(entry)) {
        throw new Error(`"extends" target must be a .yaml or .yml file: "${entry}".`);
      }
      const childPath = path.resolve(path.dirname(filePath), entry);
      const childRules = await loadAndMerge(childPath, nextAncestors, depth + 1, addExtends);
      Object.assign(merged, childRules);
      continue;
    }

    throw new Error(`"${entry}" is not a valid spectral identifier, file path, or valid URL.`);
  }

  if ('rules' in parsed && isPlainObject(parsed.rules)) {
    // Parent rules take precedence over any inherited from children.
    Object.assign(merged, parsed.rules);
  }

  return merged;
}

/**
 * Validates a remote `extends` URL before it is fetched, guarding against SSRF:
 * the URL must be https, must not target a loopback/private host, and must not
 * resolve (via DNS) to a private or loopback address.
 */
async function assertRemoteUrlAllowed(rawUrl: string): Promise<void> {
  let url: URL;
  try {
    url = new URL(rawUrl);
  } catch {
    throw new Error(`Remote "extends" is not a valid URL: "${rawUrl}".`);
  }

  if (url.protocol !== 'https:') {
    throw new Error(`Remote "extends" must use https: "${rawUrl}".`);
  }

  const { hostname } = url;
  if (isPrivateOrLoopbackHost(hostname)) {
    throw new Error(`Remote "extends" points to a disallowed host: "${hostname}".`);
  }

  // IP literals were already checked above; only real hostnames need resolving.
  if (!isIpLiteral(hostname)) {
    const addresses = await dns.promises.lookup(hostname, { all: true });
    for (const { address } of addresses) {
      if (isPrivateOrLoopbackHost(address)) {
        throw new Error(
          `Remote "extends" host "${hostname}" resolves to a private or loopback address: "${address}".`,
        );
      }
    }
  }
}

/**
 * Fetches a remote ruleset, validates it and recursively validates any nested
 * remote `extends` it declares. Remote rule content is never merged into the
 * bundle — only validated.
 */
async function fetchAndValidateRemote(rawUrl: string, depth: number): Promise<void> {
  if (depth > MAX_EXTENDS_DEPTH) {
    throw new Error('"extends" nested too deeply.');
  }

  const response = await fetch(rawUrl);
  if (!response.ok) {
    throw new Error(`Failed to fetch remote Spectral ruleset "${rawUrl}" (status ${response.status}).`);
  }

  const body = await response.text();
  const result = validateSpectralRuleset(body);
  if (!result.isValid) {
    throw new Error(`Invalid Spectral ruleset from remote extends "${rawUrl}" — failed validation: ${result.error}`);
  }

  const parsed = parse(body);
  if (!isPlainObject(parsed)) {
    return;
